// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;

    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }

    function testFuzz_property(address maybeOwner) public {
        vm.assume(maybeOwner != address(0));

        bool ok;
        try c.owner() returns (address o) {
            ok = (o != address(c));
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
